	    OuterBox.Min = FVector(D.DeltaCenter.X - OuterRadius,
	                           D.DeltaCenter.Y - OuterRadius,
	                           D.WindImpulseBounds.Min.Z);
	    OuterBox.Max = FVector(D.DeltaCenter.X + OuterRadius,
	                           D.DeltaCenter.Y + OuterRadius,
	                           D.WindImpulseBounds.Max.Z);
